const body = $input.first().json.body || $input.first().json;
const appUrl = $env.ASF_CALLBACK_BASE_URL || $env.APP_URL || 'http://localhost:3000';
const projectName = body.project_name || body.project?.name || 'Project';
const videoTitle = body.video_title || body.video?.title || 'Video';
const scene = body.scene || body.next_scene || {};
const sceneNumber = scene.scene_number || scene.sceneNumber || '?';
const sceneTitle = scene.title || `Scene ${sceneNumber}`;
const characters = (body.character_names || []).join(', ') || '—';
const prompt = body.scene_prompt || scene.flow_prompt || '(open Flow Package)';
const packagePath = scene.flow_package_path || body.flow_package_path || '/projects';
const packageUrl = packagePath.startsWith('http') ? packagePath : `${appUrl.replace(/\/$/, '')}${packagePath.startsWith('/') ? '' : '/'}${packagePath}`;
const text = [
  `ASF scene ready for manual Google Flow generation`,
  `Project: ${projectName}`,
  `Video: ${videoTitle}`,
  `Scene: #${sceneNumber} — ${sceneTitle}`,
  `Characters: ${characters}`,
  `Status: ${scene.state || body.scene_status || 'awaiting_manual_generation'}`,
  `Flow Package: ${packageUrl}`,
  '',
  'Prompt (copy in ASF UI / normal Chrome Flow):',
  prompt,
  '',
  'Do not use browser automation against Google Flow.',
].join('\n');
return [{ json: { text, packageUrl, projectName, videoTitle, sceneNumber, sceneTitle, characters, prompt } }];
